package xray

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/levvs-one/sora-client/core/engine"
	"github.com/levvs-one/sora-client/core/engine/enginetest"
)

// TestBinaryAcceptsMLDSA65Verify is the `xray run -test` verification
// behind the catalog's FeatureRealityMLDSA65 claim (CENSOR-P1): the
// key is generated by the probed binary itself (`xray mldsa65`), the
// render must be accepted as-is, and a malformed key must be refused
// by the binary — proving the field is really read, not ignored. If a
// future Xray renames or drops mldsa65Verify, this test fails before
// the claim can route plans into a silently weaker handshake.
func TestBinaryAcceptsMLDSA65Verify(t *testing.T) {
	bin := os.Getenv("SORA_XRAY_BIN")
	if bin == "" {
		dir := os.Getenv("SORA_ENGINES_DIR")
		if dir == "" {
			t.Skip("set SORA_ENGINES_DIR or SORA_XRAY_BIN to check the render with Xray")
		}
		bin = filepath.Join(dir, "xray")
	}
	gen, err := exec.CommandContext(t.Context(), bin, "mldsa65").Output()
	if err != nil {
		t.Fatalf("xray mldsa65: %v", err)
	}
	var verify string
	for _, line := range strings.Split(string(gen), "\n") {
		if v, ok := strings.CutPrefix(line, "Verify: "); ok {
			verify = strings.TrimSpace(v)
		}
	}
	if verify == "" {
		t.Fatalf("xray mldsa65 printed no Verify key:\n%s", gen)
	}
	renderWith := func(key string) string {
		p := enginetest.Plan(engine.ProtocolVLESS)
		p.Outbounds[0].TLS.RealityMLDSA65Verify = key
		raw, err := Render(p, testRuntime, nil)
		if err != nil {
			t.Fatal(err)
		}
		cfg := filepath.Join(t.TempDir(), "config.json")
		if err := os.WriteFile(cfg, raw, 0o600); err != nil {
			t.Fatal(err)
		}
		return cfg
	}
	if out, err := exec.CommandContext(t.Context(), bin, "run", "-test", "-c", renderWith(verify)).CombinedOutput(); err != nil {
		t.Fatalf("xray refused the mldsa65Verify render: %v\n%s", err, out)
	}
	if out, err := exec.CommandContext(t.Context(), bin, "run", "-test", "-c", renderWith("AAAA")).CombinedOutput(); err == nil {
		t.Fatalf("xray accepted a malformed mldsa65Verify; the field is not being read:\n%s", out)
	}
}
